SELECT i.i_category AS category, p.p_promo_name AS promotion_name, SUM(cs.cs_net_profit) AS total_net_profit, AVG(cs.cs_ext_discount_amt) AS avg_discount_amount, AVG(inv.inv_quantity_on_hand) AS avg_inventory_on_hand, COUNT(DISTINCT cs.cs_order_number) AS distinct_orders, RANK() OVER (ORDER BY SUM(cs.cs_net_profit) DESC) AS profit_rank FROM catalog_sales cs JOIN customer c ON cs.cs_bill_customer_sk = c.c_customer_sk JOIN item i ON cs.cs_item_sk = i.i_item_sk JOIN promotion p ON cs.cs_promo_sk = p.p_promo_sk JOIN inventory inv ON i.i_item_sk = inv.inv_item_sk WHERE cs.cs_sold_date_sk BETWEEN 2450820 AND 2450825 AND cs.cs_ext_tax > 0 AND p.p_discount_active = 'Y' GROUP BY i.i_category, p.p_promo_name HAVING SUM(cs.cs_net_profit) > 1000 ORDER BY total_net_profit DESC LIMIT 20
